const entries = $input.all().flatMap(item => {
  const data = item.json;

  if (Array.isArray(data)) return data;
  if (Array.isArray(data.items)) return data.items;
  if (Array.isArray(data.data)) return data.data;

  return [data];
});

const reportQueryFiles = entries
  .filter(entry =>
    entry &&
    entry.type === 'file' &&
    typeof entry.path === 'string' &&
    entry.path.includes('reports/') &&
    entry.path.endsWith('.txt')
  );

return reportQueryFiles.map(file => ({
  json: {
    report_query_path: file.path
  }
}));

// Get the base64 content
const base64Content = $input.first().json.content;

// Decode from base64
const decodedContent = Buffer.from(base64Content, 'base64').toString('utf-8');

// Return the decoded content
return {
  json: {
    netauto_agent_prompt: decodedContent
  }
};

// Get the base64 content
const base64Content = $input.first().json.content;

// Decode from base64
const decodedContent = Buffer.from(base64Content, 'base64').toString('utf-8');

// Return the decoded content
return {
  json: {
    ticketing_agent_prompt: decodedContent
  }
};

const items = $input.all();

const output = items.map(item => {
  let outputText = item.json.output;

  // Remove markdown code block markers (```json and ```)
  outputText = outputText.replace(/```json\n?/g, '').replace(/```/g, '').trim();

  // Parse the JSON string into an object
  const parsedJson = JSON.parse(outputText);

  return { json: parsedJson };
});

return output;

// Return the files data
const items = $input.all();

const output = items.map(item => {
  return {
    json: {
      report_url: item.json.content.html_url,
      report_tag: item.json.commit.message
    }
  };
});

return output;

// Get the base64 content
const source = $input.first().json;
const base64Content = source.content;

// Decode from base64
const text = Buffer.from(base64Content, 'base64').toString('utf-8');

// Ensure it's a string
const raw = typeof text === 'string' ? text : JSON.stringify(text);

// Split into lines
const lines = raw.split('\n');

// Object to store parsed fields
const result = {
  report_query_path: source.path
};

for (const line of lines) {
  // Match pattern: - Key: Value
  const match = line.match(/-\s*(.+?):\s*(.+)/);
  if (match) {
    const key = match[1]
      .trim()
      .toLowerCase()
      .replace(/\s+/g, '_'); // e.g. "File Prefix" -> "file_prefix"

    const value = match[2].trim();
    result[key] = value;
  }
}

// Return as JSON
return [
  {
    json: result
  }
];

// Get all incoming items
const items = $input.all();

// Merge all json objects into one
const merged = {};

for (const item of items) {
  Object.assign(merged, item.json);
}

// Return as a single item
return [
  {
    json: merged
  }
];

// Get all incoming items
const items = $input.all();

// Merge all json objects into one
const merged = {};

for (const item of items) {
  Object.assign(merged, item.json);
}

// Return as a single item
return [
  {
    json: merged
  }
];

//Random string for session IDs in memory
return [{
  json: {
    executionId: Math.random().toString(36).substring(2, 9)
  }
}];

